// Title: Export an Aspose.Cells workbook to HTML with gridlines disabled and programmatically verify the output in C#
// Common Searches: C# Aspose.Cells export workbook to HTML without gridlines example | How to disable gridlines when saving Excel to HTML using Aspose.Cells | Verify absence of gridlines in HTML generated by Aspose.Cells in C# | Aspose.Cells HtmlSaveOptions ExportGridLines false usage in .NET | Check generated HTML for border CSS after disabling gridlines with Aspose.Cells
// Tags: Aspose.Cells HtmlSaveOptions ExportGridLines false | C# save workbook as HTML without gridlines | disable gridlines in HTML export Aspose.Cells | validate HTML output for missing border styles Aspose.Cells | export Excel to HTML without borders using Aspose.Cells

using System;
using System.IO;
using Aspose.Cells;

// The sample creates a workbook, fills a few cells, configures HtmlSaveOptions with ExportGridLines set to false, saves the workbook as an HTML file, then reads the file to confirm it exists and checks that the HTML content does not contain any "border:" CSS, proving that gridlines were omitted.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook and add some sample data
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];
            sheet.Cells["A1"].PutValue("Header1");
            sheet.Cells["B1"].PutValue("Header2");
            sheet.Cells["A2"].PutValue(123);
            sheet.Cells["B2"].PutValue(456);

            // Define output HTML file path
            string htmlPath = "output.html";

            // Configure HTML save options to disable gridlines
            HtmlSaveOptions saveOptions = new HtmlSaveOptions(SaveFormat.Html)
            {
                ExportGridLines = false
            };

            // Save the workbook as HTML with the specified options
            workbook.Save(htmlPath, saveOptions);

            // Verify that the HTML file was created
            if (!File.Exists(htmlPath))
            {
                Console.WriteLine($"Error: The file '{htmlPath}' was not created.");
                return;
            }

            // Load the generated HTML content
            string htmlContent = File.ReadAllText(htmlPath);

            // Simple verification: check that the HTML does not contain CSS border definitions for gridlines
            bool gridLinesAbsent = !htmlContent.Contains("border:");

            // Output verification result
            Console.WriteLine(gridLinesAbsent
                ? "Verification passed: Gridlines are absent in the HTML output."
                : "Verification failed: Gridlines are present in the HTML output.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
